class Solution {
public:
    int visibleMountains(std::vector<std::vector<int>>& peaks) {
        std::map<std::pair<int, int>, int> counts;
        for (const auto& p : peaks) counts[{p[0], p[1]}]++;
        struct Interval {
            int l, r, count;
        };
        std::vector<Interval> intervals;
        for (auto& [pt, c] : counts) {
            intervals.push_back({pt.first - pt.second, pt.first + pt.second, c});
        }
        std::sort(intervals.begin(), intervals.end(), [](const Interval& a, const Interval& b) {
            if (a.l != b.l) return a.l < b.l;
            return a.r > b.r;
        });
        int ans = 0, max_r = -2e9;
        for (const auto& iv : intervals) {
            if (iv.r > max_r) {
                if (iv.count == 1) ans++;
                max_r = iv.r;
            }
        }
        return ans;
    }
};

class Solution {
    public int visibleMountains(int[][] peaks) {
        java.util.Map<String, Integer> counts = new java.util.HashMap<>();
        for (int[] p : peaks) {
            String key = p[0] + "," + p[1];
            counts.put(key, counts.getOrDefault(key, 0) + 1);
        }
        int[][] intervals = new int[counts.size()][3];
        int idx = 0;
        for (var entry : counts.entrySet()) {
            String[] parts = entry.getKey().split(",");
            int x = Integer.parseInt(parts[0]), y = Integer.parseInt(parts[1]);
            intervals[idx][0] = x - y;
            intervals[idx][1] = x + y;
            intervals[idx][2] = entry.getValue();
            idx++;
        }
        java.util.Arrays.sort(intervals, (a, b) -> {
            if (a[0] != b[0]) return Integer.compare(a[0], b[0]);
            return Integer.compare(b[1], a[1]);
        });
        int ans = 0, maxR = Integer.MIN_VALUE;
        for (int[] iv : intervals) {
            if (iv[1] > maxR) {
                if (iv[2] == 1) ans++;
                maxR = iv[1];
            }
        }
        return ans;
    }
}

var visibleMountains = function(peaks) {
    const counts = new Map();
    for (const [x, y] of peaks) {
        const key = `${x},${y}`;
        counts.set(key, (counts.get(key) || 0) + 1);
    }
    const intervals = [];
    for (const [key, count] of counts.entries()) {
        const [x, y] = key.split(',').map(Number);
        intervals.push([x - y, x + y, count]);
    }
    intervals.sort((a, b) => {
        if (a[0] !== b[0]) return a[0] - b[0];
        return b[1] - a[1];
    });
    let ans = 0, maxR = -Infinity;
    for (const [l, r, count] of intervals) {
        if (r > maxR) {
            if (count === 1) ans++;
            maxR = r;
        }
    }
    return ans;
};
